{"code":"import pandas as pd, statsmodels.api as sm
df=pd.read_csv('data/explore.csv'); xs=['canopy_cover','soil_moisture','elevation_m','road_dist_km','leaf_litter','temperature_c','slope_deg','nitrate','grazing_index','rainfall_mm']; reg=pd.get_dummies(df.region,drop_first=True,dtype=float)
for x in xs:
 d=df[[x,'species_richness']].join(reg).dropna(); m=sm.OLS(d.species_richness,sm.add_constant(d[[x]+list(reg.columns)])).fit()
 print(x, round(m.params[x],4),round(m.pvalues[x],5),len(d))
d=df[['species_richness']+xs].join(reg).dropna(); m=sm.OLS(d.species_richness,sm.add_constant(d[xs+list(reg.columns)])).fit(); print(m.summary())"}
